        /// </since>
        /// <seealso cref="Brutal.SdlApi.Ttf.SdlTtf.PInvoke.GetFontSize"/>
        public bool SetSizeDPI(float ptsize, int hdpi, int vdpi) => SdlTtf.SetFontSizeDPI(this, ptsize, hdpi, vdpi);

        /// <summary>
        ///   Set a font's current style.
        /// </summary>
        /// <param name="style">the new style values to set, OR'd together.</param>
        /// <remarks>
        ///   <para>
        ///     This updates any TTF_Text objects using this font, and clears
        ///     already-generated glyphs, if any, from the cache.
        ///   </para>
        ///   <para>
        ///     The font styles are a set of bit flags, OR'd together:
        ///   </para>
        ///   <para>
        ///     - <c>TTF_STYLE_NORMAL</c> (is zero)
        ///     - <c>TTF_STYLE_BOLD</c>
        ///     - <c>TTF_STYLE_ITALIC</c>
        ///     - <c>TTF_STYLE_UNDERLINE</c>
        ///     - <c>TTF_STYLE_STRIKETHROUGH</c>
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should be called on the thread that created the
        ///   font.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL_ttf 3.0.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Ttf.SdlTtf.PInvoke.GetFontStyle"/>
        public void SetStyle(TtfFontStyleFlags style) => SdlTtf.SetFontStyle(this, style);

        /// <summary>
        ///   Set a font's current wrap alignment option.
        /// </summary>
        /// <param name="align">the new wrap alignment option.</param>
        /// <remarks>
        ///   <para>
        ///     This updates any TTF_Text objects using this font.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should be called on the thread that created the
        ///   font.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL_ttf 3.0.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Ttf.SdlTtf.PInvoke.GetFontWrapAlignment"/>
        public void SetWrapAlignment(TtfHorizontalAlignment align) => SdlTtf.SetFontWrapAlignment(this, align);
    }
}
